insert into passages (id, text, difficulty_level, b, active) values
('cdc8153a-84d4-479c-a8d4-f3c20ac881fc', 'Tom has a small dog named Max. Every morning, Tom takes Max for a walk in the park near their house. Max loves to run and play with other dogs. After the walk, Tom gives Max fresh water and food. In the afternoon, Max likes to sleep in the sun by the window. When Tom comes home from work, Max runs to the door and wags his tail happily. Tom and Max are best friends, and they spend every evening together watching television or playing in the yard.', 1, -2.0, true),
('924335eb-88af-4fe5-a48d-3e682b3f10d4', 'The phenomenon of groupthink, first described by psychologist Irving Janis, occurs when the desire for consensus within a cohesive group overrides members'' motivation to realistically evaluate alternative courses of action. Janis identified this pattern while analyzing several major foreign policy failures, noting that highly capable individuals, when operating within a tightly knit decision-making body, often suppress dissenting opinions rather than risk disrupting group harmony. Symptoms of groupthink include an illusion of invulnerability, collective rationalization of warning signs, and direct pressure on any member who expresses doubts about the group''s shared assumptions. Paradoxically, organizations composed of highly intelligent and experienced individuals may be especially susceptible, since strong group cohesion and a history of past successes can breed overconfidence. To counteract groupthink, some organizations now formally designate a devil''s advocate whose explicit role is to challenge prevailing assumptions, while others encourage anonymous feedback channels to surface dissent that might otherwise go unspoken.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('07e44edd-4ed4-4717-8fca-e4612c13bbf5', 'sentence_completion', 'The ice cream melted quickly because the day was very ___.', NULL, '[{"id": "c", "text": "hot"}, {"id": "b", "text": "windy"}, {"id": "d", "text": "cold"}, {"id": "a", "text": "cloudy"}]'::jsonb, 0, '{"strategy": "melted quickly = נמס מהר. איזה יום גורם לגלידה להימס?", "correct_reason": "hot = חם. יום חם גורם להמסה מהירה.", "options_analysis": ["נכון! hot = חם — יום חם ממיס גלידה מהר", "windy = סוער — לא קשור להמסה", "cold = קר — הפוך, קור לא ממיס גלידה", "cloudy = מעונן — לא בהכרח חם"]}', 1.25, -2.0, 0.25, 1, 'ai', NULL, true),
('94d96c68-67ff-4428-84a3-713d2c021df8', 'sentence_completion', 'He put on his coat because it was ___ outside.', NULL, '[{"id": "c", "text": "sunny"}, {"id": "b", "text": "freezing"}, {"id": "d", "text": "warm"}, {"id": "a", "text": "dry"}]'::jsonb, 1, '{"strategy": "put on his coat = לבש מעיל. למה לובשים מעיל?", "correct_reason": "freezing = קפוא/קר מאוד. קור מאוד גורם ללבישת מעיל.", "options_analysis": ["sunny = שמשי — לא בהכרח קר", "נכון! freezing = קפוא — סיבה טבעית ללבישת מעיל", "warm = חם — הפוך, לא לובשים מעיל כשחם", "dry = יבש — לא קשור למעיל"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('2eddf70c-344c-4dc2-a674-7c4b74b5b2b4', 'restatement', 'The dog barked loudly at the mailman.', NULL, '[{"id": "d", "text": "The dog was silent when the mailman came."}, {"id": "b", "text": "The dog was afraid of the mailman."}, {"id": "c", "text": "The dog made a loud noise at the mailman."}, {"id": "a", "text": "The mailman barked at the dog."}]'::jsonb, 2, '{"strategy": "barked loudly = נבח בקול רם. פעולה פשוטה.", "correct_reason": "''made a loud noise'' = תיאור זהה לנביחה בקול רם.", "options_analysis": ["''שקט'' סותר ''barked loudly''", "לא נאמר במקור על פחד", "נכון! ''רעש חזק'' = אותה פעולה כמו נביחה בקול רם", "הפוך תפקידים — הכלב נבח, לא הדוור"]}', 1.27, -2.0, 0.25, 1, 'ai', NULL, true),
('eff72cc4-fee9-4755-bbff-a11515cf9e3f', 'restatement', 'The children ate breakfast before going to school.', NULL, '[{"id": "d", "text": "The children went to school and then ate breakfast."}, {"id": "c", "text": "The children ate breakfast at school."}, {"id": "a", "text": "The children skipped breakfast before school."}, {"id": "b", "text": "The children ate breakfast first, then went to school."}]'::jsonb, 3, '{"strategy": "before going to school = לפני שהלכו לבית הספר. סדר פעולות.", "correct_reason": "''ate breakfast first, then went to school'' = אותו סדר בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר את ''before'' — לא באו לאכול בביה''ס", "סותר — הם כן אכלו ארוחת בוקר", "נכון! אותו סדר בדיוק: קודם אכלו, אחר כך הלכו"]}', 1.5, -2.0, 0.25, 1, 'ai', NULL, true),
('48b598ff-2a33-4016-b039-4b8a15f60f69', 'restatement', 'This book is more interesting than that one.', NULL, '[{"id": "a", "text": "That book is less interesting than this one."}, {"id": "d", "text": "This book is less interesting than that one."}, {"id": "b", "text": "That book is more interesting than this one."}, {"id": "c", "text": "Both books are equally interesting."}]'::jsonb, 0, '{"strategy": "יחס השוואתי הפוך: זה מעניין יותר מ-''that'' = ''that'' פחות מעניין מ-''this''.", "correct_reason": "''that book is less interesting than this one'' = אותו יחס בדיוק הפוך.", "options_analysis": ["נכון! אותו יחס בדיוק, רק הפוך כיוון", "סותר — במקור ''this'' יותר מעניין, לא פחות", "הפוך תפקידים — במקור ''this'' יותר מעניין", "סותר את קיום ההשוואה"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
('76c8f20b-da39-4fdd-8e42-210ab34fc2bd', 'restatement', 'She always brushes her teeth before bed.', NULL, '[{"id": "b", "text": "She brushes her teeth after waking up."}, {"id": "c", "text": "She brushes her teeth every night before sleeping."}, {"id": "d", "text": "She sometimes brushes her teeth before bed."}, {"id": "a", "text": "She never brushes her teeth before bed."}]'::jsonb, 1, '{"strategy": "always...before bed = תמיד לפני השינה. הרגל קבוע.", "correct_reason": "''every night before sleeping'' = ''always'' = בכל לילה, אותה משמעות.", "options_analysis": ["''אחרי היקיצה'' סותר ''before bed''", "נכון! ''בכל לילה לפני שינה'' = ''always before bed''", "''לפעמים'' חלש מ-''always''", "''אף פעם לא'' סותר ''always''"]}', 1.39, -2.0, 0.25, 1, 'ai', NULL, true),
('a1dfcb0d-dfba-4492-a7b9-eb93b5e18fa5', 'restatement', 'The boy was happy because he got a new bicycle.', NULL, '[{"id": "d", "text": "The boy was happy even though he had no bicycle."}, {"id": "c", "text": "The boy did not want a new bicycle."}, {"id": "b", "text": "Getting a new bicycle made the boy happy."}, {"id": "a", "text": "The boy was sad because he lost his bicycle."}]'::jsonb, 2, '{"strategy": "happy because got a bicycle = שמח בגלל אופניים חדשים. סיבה-תוצאה.", "correct_reason": "''getting a new bicycle made the boy happy'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר ''because he got'' — יש לו אופניים", "סותר — הוא כן קיבל את האופניים", "נכון! אותה סיבה-תוצאה בדיוק", "סותר לגמרי — הוא קיבל אופניים, לא איבד"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('2567b705-0e65-47b2-b278-e1543383a2b6', 'restatement', 'The soup needs more salt.', NULL, '[{"id": "d", "text": "The soup already has too much salt."}, {"id": "b", "text": "The soup needs less salt."}, {"id": "c", "text": "The soup does not need any salt."}, {"id": "a", "text": "There is not enough salt in the soup."}]'::jsonb, 3, '{"strategy": "needs more salt = צריך עוד מלח. חסר מלח.", "correct_reason": "''not enough salt'' = חסר מלח = אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''too much'' סותר ''needs more''", "הפוך — ''less'' סותר ''more''", "סותר ''needs more salt''", "נכון! ''לא מספיק מלח'' = ''needs more salt''"]}', 1.47, -2.0, 0.25, 1, 'ai', NULL, true),
('5fddc43c-bb63-44cc-aefb-2f428edc84d6', 'reading_comprehension', 'What is the passage mainly about?', 'cdc8153a-84d4-479c-a8d4-f3c20ac881fc', '[{"id": "d", "text": "Tom''s daily routine with his dog Max"}, {"id": "a", "text": "How to train a dog to walk"}, {"id": "b", "text": "A park near Tom''s house"}, {"id": "c", "text": "Tom''s job and daily schedule"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה מתארת יום טיפוסי של טום ומקס.", "correct_reason": "כל הפסקה עוסקת בשגרה היומית של טום עם הכלב שלו.", "options_analysis": ["נכון! שגרת היום של טום עם מקס = הנושא הכולל", "לא מוזכר בפסקה כלל", "פרט משני, לא הנושא המרכזי", "לא מוזכר בפירוט, רק ברמז קצר"]}', 1.39, -2.0, 0.25, 1, 'ai', NULL, true),
('e32f3fc3-2603-4831-a838-47879a09d2b9', 'reading_comprehension', 'What does Tom do with Max every morning?', 'cdc8153a-84d4-479c-a8d4-f3c20ac881fc', '[{"id": "b", "text": "Feeds him only"}, {"id": "a", "text": "Takes him for a walk in the park"}, {"id": "c", "text": "Takes him to work"}, {"id": "d", "text": "Watches television with him"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את פעילות הבוקר בפסקה.", "correct_reason": "הפסקה אומרת: ''Every morning, Tom takes Max for a walk in the park''.", "options_analysis": ["לא מדויק — יש גם האכלה אך אחרי הטיול", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "זה קורה בערב, לא בבוקר"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('deae3f39-a1de-47da-8d59-e6f0e4485111', 'reading_comprehension', 'What does Max like to do in the afternoon?', 'cdc8153a-84d4-479c-a8d4-f3c20ac881fc', '[{"id": "d", "text": "Eat his food"}, {"id": "a", "text": "Play with other dogs"}, {"id": "b", "text": "Sleep in the sun by the window"}, {"id": "c", "text": "Run in the park"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את פעילות אחר הצהריים בפסקה.", "correct_reason": "הפסקה אומרת: ''In the afternoon, Max likes to sleep in the sun by the window''.", "options_analysis": ["לא מוזכר כפעילות אחר הצהריים", "זה קורה בבוקר בטיול, לא אחר הצהריים", "נכון! נאמר במפורש בפסקה", "זה קורה בבוקר, לא אחר הצהריים"]}', 1.16, -2.0, 0.25, 1, 'ai', NULL, true),
('45126bca-369d-43e0-9a99-f09f4eaece9e', 'reading_comprehension', 'How does Max react when Tom comes home?', 'cdc8153a-84d4-479c-a8d4-f3c20ac881fc', '[{"id": "a", "text": "He goes to sleep"}, {"id": "d", "text": "He ignores Tom"}, {"id": "c", "text": "He barks angrily"}, {"id": "b", "text": "He runs to the door and wags his tail happily"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את התגובה של מקס בפסקה.", "correct_reason": "הפסקה אומרת: ''Max runs to the door and wags his tail happily''.", "options_analysis": ["סותר את הפסקה — הוא לא הולך לישון, הוא רץ לדלת", "הפוך — הוא דווקא מגיב בהתלהבות", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.4, -2.0, 0.25, 1, 'ai', NULL, true),
('1b86051b-7958-4f58-8c91-3f2548caf941', 'reading_comprehension', 'What do Tom and Max do together every evening?', 'cdc8153a-84d4-479c-a8d4-f3c20ac881fc', '[{"id": "c", "text": "Watch television or play in the yard"}, {"id": "d", "text": "Go to the park"}, {"id": "b", "text": "Go to work together"}, {"id": "a", "text": "Sleep by the window"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את פעילות הערב בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''they spend every evening together watching television or playing in the yard''.", "options_analysis": ["נכון! נאמר במפורש בסוף הפסקה", "זה פעילות הבוקר, לא הערב", "לא נאמר בפסקה כלל", "זה פעילות אחר הצהריים של מקס בלבד"]}', 1.28, -2.0, 0.25, 1, 'ai', NULL, true),
('aba29bcc-1fbf-494f-bcf4-8c91ddf9219f', 'sentence_completion', 'The politician''s ___ remarks avoided directly answering any of the reporters'' questions.', NULL, '[{"id": "b", "text": "precise"}, {"id": "d", "text": "evasive"}, {"id": "a", "text": "candid"}, {"id": "c", "text": "blunt"}]'::jsonb, 1, '{"strategy": "avoided directly answering = נמנע ממענה ישיר. איזה סוג תשובה מתחמק?", "correct_reason": "evasive = מתחמק. תשובות שמימנעות ממתן תשובה ישירה.", "options_analysis": ["precise = מדויק — הפוך מתשובה מתחמקת", "נכון! evasive = מתחמק — מתאים להתנהגות של הימנעות מתשובה", "candid = כן/גלוי לב — הפוך מהתחמקות", "blunt = ישיר/גס — הפוך מהתחמקות"]}', 1.45, 2.0, 0.25, 5, 'ai', NULL, true),
('2aa92747-4972-4458-a6c1-4b2d9bfa0633', 'sentence_completion', 'The evidence presented in court was largely ___, relying more on assumption than fact.', NULL, '[{"id": "b", "text": "verified"}, {"id": "c", "text": "irrefutable"}, {"id": "d", "text": "circumstantial"}, {"id": "a", "text": "conclusive"}]'::jsonb, 2, '{"strategy": "relying on assumption than fact = מתבסס על השערה ולא עובדה. איזו ראיה כזו?", "correct_reason": "circumstantial = נסיבתי. ראיה נסיבתית מבוססת על הסקה ולא עובדה ישירה.", "options_analysis": ["verified = מאומת — הפוך מהתבססות על השערה", "irrefutable = בלתי ניתן להפרכה — הפוך מראיה חלשה", "נכון! circumstantial = נסיבתי — מבוסס על הסקה ולא עובדה ישירה", "conclusive = חד-משמעי — הפוך, ראיה חלשה אינה חד-משמעית"]}', 1.35, 2.0, 0.25, 5, 'ai', NULL, true),
('0fda63f9-958d-4385-ba3a-ab3bd9f4b2de', 'restatement', 'So thoroughly had the committee reviewed the proposal that no objections were raised.', NULL, '[{"id": "a", "text": "The committee''s careless review led to many objections."}, {"id": "b", "text": "No one reviewed the proposal, so objections were raised."}, {"id": "d", "text": "The committee rejected the proposal without reviewing it."}, {"id": "c", "text": "The committee''s thorough review of the proposal left no room for objections."}]'::jsonb, 3, '{"strategy": "so thoroughly...that = כה ביסודיות...עד ש-. סקירה יסודית הובילה לחוסר התנגדויות.", "correct_reason": "''thorough review left no room for objections'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''careless'' סותר ''thoroughly''", "סותר ''reviewed'' — הם כן סקרו", "סותר לגמרי — הם כן סקרו את ההצעה ביסודיות", "נכון! אותה סיבה-תוצאה בדיוק: סקירה יסודית → אין התנגדויות"]}', 1.24, 2.0, 0.25, 5, 'ai', NULL, true),
('49dec9a5-3cf6-4a96-a6cb-91143c063605', 'restatement', 'Scarcely had the announcement been made when share prices began to fall.', NULL, '[{"id": "b", "text": "Share prices fell almost immediately after the announcement was made."}, {"id": "d", "text": "Share prices remained stable despite the announcement."}, {"id": "a", "text": "The announcement was made long after share prices fell."}, {"id": "c", "text": "Share prices rose steadily before the announcement."}]'::jsonb, 0, '{"strategy": "scarcely...when = בקושי...כש-. משמעות: כמעט מיד אחרי.", "correct_reason": "''fell almost immediately after the announcement'' = אותה סמיכות זמנים בדיוק.", "options_analysis": ["נכון! ''כמעט מיד אחרי ההודעה'' = אותה סמיכות זמנים בדיוק כמו ''scarcely...when''", "סותר ''began to fall'' — היה שינוי, לא יציבות", "הופך את סדר הזמנים — ההודעה קדמה לירידה", "הפוך — ''rose'' סותר ''fall'', וגם הסדר שגוי"]}', 1.36, 2.0, 0.25, 5, 'ai', NULL, true),
('40d64434-fd7e-445a-a999-291835edea93', 'restatement', 'Were it not for his quick thinking, the accident could have been far worse.', NULL, '[{"id": "d", "text": "The accident was worse because of his slow thinking."}, {"id": "a", "text": "His quick thinking prevented the accident from being far worse."}, {"id": "b", "text": "He thought quickly, but it made no difference to the accident."}, {"id": "c", "text": "The accident happened because he thought too quickly."}]'::jsonb, 1, '{"strategy": "were it not for = לולא. תנאי היפותטי הפוך — החשיבה המהירה מנעה החמרה.", "correct_reason": "''quick thinking prevented the accident from being far worse'' = המשמעות הנכונה של התנאי ההפוך.", "options_analysis": ["הפוך — ''slow thinking'' סותר ''quick thinking''", "נכון! תנאי היפותטי הפוך: החשיבה המהירה מנעה החמרה", "סותר ''were it not for'' שמציין שהיה הבדל משמעותי", "הפוך לוגית — חשיבה מהירה מנעה את התאונה, לא גרמה לה"]}', 1.16, 2.0, 0.25, 5, 'ai', NULL, true),
('aff2cf50-7298-4e40-9140-b9fadd24105f', 'restatement', 'The findings, controversial as they were, prompted a wave of further research.', NULL, '[{"id": "b", "text": "Further research disproved the controversial findings immediately."}, {"id": "a", "text": "The findings were ignored because they were controversial."}, {"id": "c", "text": "Despite being controversial, the findings led to more research being conducted."}, {"id": "d", "text": "The findings were so uncontroversial that no further research was needed."}]'::jsonb, 2, '{"strategy": "controversial as they were...prompted = שנוי במחלוקת ככל שהיה, עדיין הוביל למחקר נוסף.", "correct_reason": "''despite being controversial, led to more research'' = אותה משמעות בדיוק של ניגוד ותוצאה.", "options_analysis": ["לא נאמר במקור שהמחקר הפריך את הממצאים", "סותר ''prompted a wave of further research''", "נכון! אותה משמעות בדיוק: למרות המחלוקת, הובילו למחקר נוסף", "סותר ''controversial'' לגמרי"]}', 1.04, 2.0, 0.25, 5, 'ai', NULL, true),
('f9539023-d9f3-48b0-9269-4eb3fc427d36', 'restatement', 'Little did the investors realize how volatile the market would soon become.', NULL, '[{"id": "b", "text": "The market remained stable, as the investors expected."}, {"id": "c", "text": "The investors were fully aware of the market''s coming volatility."}, {"id": "d", "text": "The investors predicted the market''s volatility accurately."}, {"id": "a", "text": "The investors had no idea how unstable the market would soon be."}]'::jsonb, 3, '{"strategy": "little did...realize = כמעט ולא הבינו. חוסר מודעות למה שעתיד לקרות.", "correct_reason": "''had no idea how unstable the market would soon be'' = אותה משמעות בדיוק של חוסר מודעות.", "options_analysis": ["סותר ''volatile'' — השוק דווקא הפך תנודתי, לא נשאר יציב", "הפוך גמור — ''little did realize'' = לא היו מודעים כלל", "הפוך — הם דווקא לא צפו זאת, לפי ''little did realize''", "נכון! אותה משמעות בדיוק: לא היה להם מושג על התנודתיות הצפויה"]}', 1.19, 2.0, 0.25, 5, 'ai', NULL, true),
('48c25a6b-c38e-4ede-a9b2-7efbebed1bbd', 'restatement', 'Not until the results were independently replicated did the scientific community accept the theory.', NULL, '[{"id": "c", "text": "The scientific community only accepted the theory after independent replication confirmed the results."}, {"id": "b", "text": "Independent replication was never attempted for this theory."}, {"id": "a", "text": "The theory was rejected even after independent replication."}, {"id": "d", "text": "The scientific community accepted the theory before any replication occurred."}]'::jsonb, 0, '{"strategy": "not until...did = רק כאשר...אז. תנאי הכרחי מתהפך לחיוב.", "correct_reason": "''only accepted after independent replication confirmed'' = אותו תנאי הכרחי בדיוק.", "options_analysis": ["נכון! אותו תנאי הכרחי בדיוק: קבלה רק אחרי שכפול עצמאי", "סותר ''were independently replicated'' — השכפול כן קרה", "סותר ''accept'' — הקהילה כן קיבלה את התיאוריה", "הפוך — הקבילה רק באה אחרי השכפול, לא לפניו"]}', 1.43, 2.0, 0.25, 5, 'ai', NULL, true),
('d0d27ce6-df5c-4e08-a95e-7fd1339e4d15', 'reading_comprehension', 'What is the main idea of the passage?', '924335eb-88af-4fe5-a48d-3e682b3f10d4', '[{"id": "d", "text": "Irving Janis proved that group decisions are always superior to individual ones"}, {"id": "c", "text": "Groupthink is a psychological phenomenon in which the desire for consensus suppresses critical evaluation"}, {"id": "a", "text": "Groupthink only affects inexperienced or poorly trained groups"}, {"id": "b", "text": "Anonymous feedback channels have eliminated groupthink in most organizations"}]'::jsonb, 1, '{"strategy": "שאלת רעיון מרכזי — הפסקה מגדירה את תופעת ה-groupthink ומסבירה כיצד היא פוגעת בקבלת החלטות.", "correct_reason": "הפסקה כולה מוקדשת להגדרת התופעה, סימניה, ואמצעים להתמודדות איתה.", "options_analysis": ["הפוך — הפסקה בכלל מתארת כשל בקבלת החלטות קבוצתית", "נכון! הגדרת התופעה והשפעתה על הערכה ביקורתית = הנושא הכולל", "הפוך — הפסקה מדגישה שדווקא קבוצות מיומנות רגישות לתופעה", "המשפט האחרון מציג אמצעים אפשריים, לא הצהרה שהתופעה נעלמה"]}', 1.01, 2.0, 0.25, 5, 'ai', NULL, true),
('fa8b52c5-d307-45cd-8200-d67962f1afe4', 'reading_comprehension', 'According to the passage, why might highly intelligent groups be especially susceptible to groupthink?', '924335eb-88af-4fe5-a48d-3e682b3f10d4', '[{"id": "a", "text": "Because they lack experience in decision-making"}, {"id": "d", "text": "Because they always disagree with one another"}, {"id": "c", "text": "Because strong group cohesion and past successes can breed overconfidence"}, {"id": "b", "text": "Because they rarely communicate with each other"}]'::jsonb, 2, '{"strategy": "שאלת סיבה — חפש את ההסבר הפרדוקסלי בפסקה.", "correct_reason": "הפסקה אומרת: ''strong group cohesion and a history of past successes can breed overconfidence''.", "options_analysis": ["סותר את הפסקה — מדובר דווקא באנשים מנוסים ומיומנים", "הפוך — הפסקה מדברת על דיכוי חילוקי דעות, לא ריבוי שלהם", "נכון! ההסבר המדויק מהפסקה", "לא נאמר בפסקה, וסותר את עצם קיום הלכידות הקבוצתית"]}', 1.51, 2.0, 0.25, 5, 'ai', NULL, true),
('20b35db5-37fe-4110-9db3-4963ae745c6b', 'reading_comprehension', 'The word "suppress" in the passage most closely means:', '924335eb-88af-4fe5-a48d-3e682b3f10d4', '[{"id": "d", "text": "to celebrate publicly"}, {"id": "b", "text": "to accurately document"}, {"id": "c", "text": "to openly express and encourage"}, {"id": "a", "text": "to hold back or prevent from being expressed"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''suppress dissenting opinions'' מתייחס לבלימת דעות חולקות.", "correct_reason": "suppress = לדכא/לבלום, למנוע מהבעה גלויה.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! suppress = לדכא/לבלום מהבעה"]}', 1.1, 2.0, 0.25, 5, 'ai', NULL, true),
('1f80d3d7-93e9-4cd4-8dbe-6af6f36b857c', 'reading_comprehension', 'What is the role of a "devil''s advocate," according to the passage?', '924335eb-88af-4fe5-a48d-3e682b3f10d4', '[{"id": "d", "text": "To formally challenge prevailing assumptions within the group"}, {"id": "a", "text": "To represent the organization to outside media"}, {"id": "c", "text": "To document meeting minutes"}, {"id": "b", "text": "To agree with the majority to speed up decisions"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את התפקיד המוגדר בפסקה.", "correct_reason": "הפסקה אומרת: ''formally designate a devil''s advocate whose explicit role is to challenge prevailing assumptions''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "הפוך — התפקיד הוא לאתגר, לא להסכים"]}', 1.57, 2.0, 0.25, 5, 'ai', NULL, true),
('daaf7c54-239e-4a12-85bf-684cf08acc26', 'reading_comprehension', 'Why do some organizations encourage anonymous feedback channels, according to the passage?', '924335eb-88af-4fe5-a48d-3e682b3f10d4', '[{"id": "c", "text": "To eliminate the need for meetings entirely"}, {"id": "d", "text": "To surface dissent that might otherwise go unspoken"}, {"id": "b", "text": "To reduce the number of employees in decision-making"}, {"id": "a", "text": "To publicly reward employees who agree with leadership"}]'::jsonb, 1, '{"strategy": "שאלת סיבה — חפש את ההסבר בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''encourage anonymous feedback channels to surface dissent that might otherwise go unspoken''.", "options_analysis": ["לא נאמר בפסקה כלל", "נכון! הסיבה המדויקת מהפסקה", "לא נאמר בפסקה כלל", "הפוך — המטרה היא לעודד חילוקי דעות, לא הסכמה"]}', 1.42, 2.0, 0.25, 5, 'ai', NULL, true);